def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    seen=set()
    for r in range(h):
        for c in range(w):
            if g[r][c] in (2,7) or (r,c) in seen:
                continue
            color=g[r][c]
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and g[yy][xx]==color and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            r0=min(y for y,x in cells); r1=max(y for y,x in cells)
            c0=min(x for y,x in cells); c1=max(x for y,x in cells)
            perimeter={(y,x) for y in range(r0,r1+1) for x in range(c0,c1+1) if y in (r0,r1) or x in (c0,c1)}
            if set(cells)==perimeter and r1>r0 and c1>c0:
                for y in range(max(0,r0-1),min(h,r1+2)):
                    for x in range(max(0,c0-1),min(w,c1+2)):
                        if y in (r0-1,r1+1) or x in (c0-1,c1+1):
                            if g[y][x]==7: g[y][x]=2
    return g

